std::string resolved_language(std::string preference) {
    if(preference!="auto"&&preference!="zh-CN"&&preference!="en") throw Error(2,"Language must be auto, zh-CN or en");
    if(preference!="auto") return preference;
    auto language=GetUserDefaultUILanguage();return PRIMARYLANGID(language)==LANG_CHINESE &&
        (SUBLANGID(language)==SUBLANG_CHINESE_SIMPLIFIED||SUBLANGID(language)==SUBLANG_CHINESE_SINGAPORE) ? "zh-CN":"en";
}
void Messages::set_language(const std::string& preference) {
    const bool chinese=resolved_language(preference)=="zh-CN";std::set<std::string> ids;
    for(const auto& e:entries) {
        if(!e.id||!e.en||!*e.en||!e.zh||!*e.zh||!ids.insert(e.id).second) throw Error(1,"Invalid translation resource");
        labels_[e.id]=chinese?e.zh:e.en;
    }
}
std::string& Messages::operator[](std::string_view key) {
    auto found=labels_.find(key);if(found==labels_.end()) throw Error(1,"Missing translation: "+std::string(key));return found->second;
}
